// BRAIN_FIX_002: Brain context thread safety
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.contextimport com.roshan.persona.brain.persona.Personaimport com.roshan.persona.common.CorrelationIdimport java.time.Instantimport java.util.TimeZone/** * NOUS — Brain runtime context. * * Immutable snapshot of brain's runtime state at the moment a request is processed. * Built fresh per request by [com.roshan.persona.brain.orchestrator.BrainPreProcessor]. * * Every Brain layer receives this context — it is the universal "what we know * right now" object. Layers must NOT mutate it; if they need to add state, they * return a [BrainContext] copy via [copy] with the new value. * * Lifecycle: *   1. Created by BrainPreProcessor at the start of every request *   2. Passed through each layer (Layer 0 → 5) *   3. Discarded after post-processing *   4. Persisted to BrainTrace (audit log) for replay * * @see <a href="docs/adr/0003-multi-module-architecture.md">ADR 0003</a> */data class BrainContext(    /** Unique ID for tracing this request across the system. */    val correlationId: CorrelationId,    /** Conversation session ID (used for memory continuity). */    val sessionId: SessionId,    /** Request arrival time (UTC). */    val timestamp: Instant,    /** User's timezone (for time-aware rules + persona greetings). */    val timezone: TimeZone,    /** Currently active persona (Module 7 — Persona). */    val activePersona: Persona,    /** User identity + preferences (on-device, never sent to cloud). */    val userContext: UserContext,    /** Device state (thermal, RAM, battery, network). */    val deviceContext: DeviceContext,    /** Last N conversation turns (configurable, default 5). */    val conversationHistory: List<Turn>,    /** If a skill asked for input on the previous turn, what was it waiting for? */    val pendingExpectation: Expectation?,    /** Optional ambient context (location, weather, activity). */    val ambientContext: AmbientSnapshot?,    /** Per-request time + cost budget. Enforced by Brain orchestrator. */    val budget: BrainBudget,)/** Conversation session ID — UUID-based. */@JvmInlinevalue class SessionId(val value: String) {    override fun toString(): String = value    companion object {        fun generate(): SessionId = SessionId(java.util.UUID.randomUUID().toString())    }}/** One conversation turn (user input + brain response). */data class Turn(    val correlationId: CorrelationId,    val userText: String,    val brainResponse: String,    val timestamp: Instant,    val intentLabel: String?,  // for debugging    val layerLabel: String?,   // which layer handled it)/** * Expectation — if a skill asked for input on the previous turn, this records * what it was waiting for. Used for contextual override (Fixes #26 — coreference). * * @see <a href="docs/spec/module2-spec-review.pdf">§4.6 ContextualOverride</a> */sealed interface Expectation {    /** Skill asked user to provide a contact (e.g., "Call who?"). */    data class AwaitingContact(val originalIntent: com.roshan.persona.brain.intent.Intent) : Expectation    /** Skill asked user to confirm an action (e.g., "Call Mom? Yes/No"). */    data class AwaitingConfirmation(val action: PendingAction) : Expectation    /** Skill asked user to pick from a list (e.g., "Which one: 3 PM or 4 PM?"). */    data class AwaitingChoice(val options: List<String>) : Expectation}/** A pending action awaiting user confirmation. */data class PendingAction(    val description: String,    val intent: com.roshan.persona.brain.intent.Intent,    val skillId: String,)/** * Per-request budget — enforced by Brain orchestrator. * * @see <a href="docs/spec/module2-spec-review.pdf">§9 Latency Budgets</a> */data class BrainBudget(    /** Hard latency ceiling in milliseconds (default 5000). */    val maxLatencyMs: Long = 5_000L,    /** Hard cost ceiling in USD (default 0.05). */    val maxCostUsd: Float = 0.05f,    /** Hard LLM token ceiling (default 1024). */    val maxLlmTokens: Int = 1_024,    /** Whether cloud LLM is allowed for this request (false = local-only mode). */    val allowCloud: Boolean = true,    /** Whether agentic (multi-step) execution is allowed. */    val allowAgentic: Boolean = true,) {    companion object {        /** Default budget — local-first, conservative. */        val DEFAULT = BrainBudget()        /** Local-only budget — for privacy mode or offline. */        val LOCAL_ONLY = BrainBudget(allowCloud = false)        /** Strict budget — for foreground quick queries. */        val STRICT = BrainBudget(            maxLatencyMs = 2_000L,            maxCostUsd = 0.01f,            maxLlmTokens = 256,            allowAgentic = false,        )        /** Generous budget — for background agentic tasks. */        val GENEROUS = BrainBudget(            maxLatencyMs = 15_000L,            maxCostUsd = 0.50f,            maxLlmTokens = 4_096,            allowAgentic = true,        )    }}